
const hero=$('.hero');$('#title').hidden=true;$('.top').append($('#title'));const tip=$('#subtitle');tip.style.cssText='font-size:10px;color:#8996aa;margin-left:12px';$('.breadcrumb').append(tip);$('.actions').append($('#create'));hero.remove();
const fullscreenButton=document.createElement('button');fullscreenButton.className='btn';fullscreenButton.textContent='全屏画布';$('.spacebar').append(fullscreenButton);fullscreenButton.onclick=()=>{const s=$('#space');const on=s.classList.toggle('expanded-screen');s.style.cssText=on?'position:fixed;inset:0;z-index:7;background:#f4f7fc;padding:15px;overflow:auto;margin:0':'';$('.spacestage').style.height=on?'calc(100dvh - 155px)':'';fullscreenButton.textContent=on?'退出全屏':'全屏画布';fitSpace()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#space').classList.contains('expanded-screen')&&!$('#veil').classList.contains('open'))fullscreenButton.click()});
const detailButton=document.createElement('button');detailButton.className='btn';detailButton.textContent='打开聚焦对象详情';detailButton.onclick=()=>{if(!focusNode){toast('请先点击节点或选择聚焦项目');return}const n=graphNodes.find(x=>x.id===focusNode);if(n.type==='project')projectDetail(n.id.slice(2));else if(n.type==='task')taskDetail(n.id.slice(2));else{const f=fileItems.find(x=>x.node===n.id);if(f)editFile(f.id);else note(n.label)}};$('.spacebar').append(detailButton);
const fitBeforeV5=fitSpace;fitSpace=function(){fitBeforeV5();if(focusNode){const r=svg.getBoundingClientRect();const n=graphNodes.find(x=>x.id===focusNode);const zoom=Math.min(1.35,Math.max(gzoom,Math.min(r.width/750,r.height/450)));if(zoom>gzoom){gzoom=zoom;gx=r.width/2-(n.x+100)*gzoom;gy=r.height/2-(n.y+43)*gzoom;transformSpace()}}};
names.space=['关联空间','关联空间','点击节点展开邻接关系 · 全局视图恢复全貌'];
